+function pptShapeType(pptx, obj) {
+  if (obj.type === 'circle') return pptx.ShapeType.ellipse;
+  if (obj.type === 'rect') return obj.radius > 0 ? pptx.ShapeType.roundRect : pptx.ShapeType.rect;
