+}
+
+function renderPptxObject(pptx, slide, obj) {
+  if (obj.type === 'rect') {
+    slide.addShape(pptShapeType(pptx, obj), {
+      x: obj.x, y: obj.y, w: obj.w, h: obj.h,
+      fill: { color: obj.fill, transparency: obj.transparency || 0 },
+      line: { color: obj.stroke || obj.fill, width: obj.strokeWidth || 0, transparency: obj.strokeWidth ? 0 : 100 },
+      radius: obj.radius || 0,
