+    slide.addShape(pptx.ShapeType.ellipse, {
+      x: obj.x, y: obj.y, w: obj.d, h: obj.d,
+      fill: { color: obj.fill },
+      line: { color: obj.stroke || obj.fill, width: obj.strokeWidth || 0, transparency: obj.strokeWidth ? 0 : 100 },
+    });
+  } else if (obj.type === 'line') {
+    const dash = obj.dash === 'dash' ? 'dash' : 'solid';
+    slide.addShape(pptx.ShapeType.line, {
+      x: obj.x1, y: obj.y1, w: obj.x2 - obj.x1, h: obj.y2 - obj.y1,
